/** A AlwaysUpFlow object. */
export type AlwaysUpFlow = {
  __typename?: 'AlwaysUpFlow';
  /** The UUID of the AlwaysUpFlow. */
  alwaysUpFlowId?: Maybe<Scalars['ID']['output']>;
  /** The ID of specific build being used. Default null to use most up to date build */
  buildId?: Maybe<Scalars['ID']['output']>;
  createdBy?: Maybe<Scalars['String']['output']>;
  /** The schedule was created UTC time zone */
  dateCreated?: Maybe<Scalars['DateTime']['output']>;
  /** Schedules last update time UTC time zone. */
  dateModified?: Maybe<Scalars['DateTime']['output']>;
  /** The ID of the engine */
  engineId?: Maybe<Scalars['ID']['output']>;
  modifiedBy?: Maybe<Scalars['String']['output']>;
  /**
   * The GUID of the organization this AlwaysUpFlow will belong to.
   * Defaults to the user's organization.
   */
  organizationGuid?: Maybe<Scalars['ID']['output']>;
  /**
   * The ID of the organization this AlwaysUpFlow will belong to.
   * Defaults to the user's organization.
   */
  organizationId?: Maybe<Scalars['ID']['output']>;
  /** The flag used to mark the pod for deletion which will start a new pod defaulting this boolean to false. */
  restart?: Maybe<Scalars['Boolean']['output']>;
  /** Scheduled value */
  schedule?: Maybe<Scalars['String']['output']>;
  /** The status enum for a schedule as it will never be deleted. */
  status?: Maybe<AlwaysUpFlowStatus>;
  /** updateScheduled value */
  updateSchedule?: Maybe<Scalars['String']['output']>;
};

export type AlwaysUpFlowInput = {
  /** The UUID of the AlwaysUpFlow. */
  alwaysUpFlowId?: InputMaybe<Scalars['ID']['input']>;
  /** The ID of specific build being used. Default null to use most up to date build */
  buildId?: InputMaybe<Scalars['ID']['input']>;
  createdBy?: InputMaybe<Scalars['String']['input']>;
  /** The schedule was created UTC time zone */
  dateCreated?: InputMaybe<Scalars['DateTime']['input']>;
  /** Schedules last update time UTC time zone. */
  dateModified?: InputMaybe<Scalars['DateTime']['input']>;
  /** The ID of the engine */
  engineId: Scalars['ID']['input'];
  modifiedBy?: InputMaybe<Scalars['String']['input']>;
  /**
   * The ID of the organization this AlwaysUpFlow will belong to.
   * Defaults to the user's organization.
   */
  organizationId?: InputMaybe<Scalars['ID']['input']>;
  /** The flag used to mark the pod for deletion which will start a new pod defaulting this boolean to false. */
  restart?: InputMaybe<Scalars['Boolean']['input']>;
  /** Scheduled value - In chron format of '* * * * * *'. Checks for ranges in hours and minutes, for example: "* 8-16 * * * " is active from 8pm to 4pm every day. */
  schedule?: InputMaybe<Scalars['String']['input']>;
  /** The status enum for a schedule as it will never be deleted. */
  status?: InputMaybe<AlwaysUpFlowStatus>;
  /**
   * This is the schedule the always up flow will be restarted. Flows must restart at least once every 24 hours.
   * Defaults to '0 4 * * *' which is midnight eastern time(4am UTC). The 'int int * * *' format is the only accepted format.
   */
  updateSchedule?: InputMaybe<Scalars['String']['input']>;
};

