/** An application is a set of Veritone functionality that customers can sign up for. */
export type Application = {
  __typename?: 'Application';
  /** The configs associated with this application */
  applicationConfig: ApplicationConfigList;
  /** The config definition associated with this application */
  applicationConfigDefinition?: Maybe<ApplicationConfigDefinitionList>;
  /** The headerbar associated with this application */
  applicationHeaderbar?: Maybe<ApplicationHeaderbar>;
  /** The roles of this application */
  applicationRoles: Array<ApplicationRole>;
  billingDirty?: Maybe<Scalars['Boolean']['output']>;
  /** Billing */
  billingPlanId?: Maybe<Scalars['ID']['output']>;
  category?: Maybe<Scalars['String']['output']>;
  /**
   * OAuth2 client secret. This field is server-generated and is only
   * returned on application creation.
   */
  clientSecret?: Maybe<Scalars['String']['output']>;
  /** @deprecated No longer supported. Components are replaced by package resources. */
  components?: Maybe<ApplicationComponent>;
  contextMenuExtensions?: Maybe<ContextMenuExtensionList>;
  createdDateTime?: Maybe<Scalars['DateTime']['output']>;
  dailyTaskMetrics?: Maybe<DailyTaskMetricsList>;
  deploymentModel?: Maybe<DeploymentModel>;
  description?: Maybe<Scalars['String']['output']>;
  details?: Maybe<Scalars['JSONData']['output']>;
  /** The tags associated with the application */
  entityTags?: Maybe<Array<Maybe<EntityTag>>>;
  /**
   * The Application event endpoint.
   * The event is delivered to the application via the Event Routing for Applications mechanism.
   */
  eventEndpoint?: Maybe<Scalars['String']['output']>;
  /** The subscription events with this application */
  eventSubscriptions?: Maybe<Array<Maybe<EventSubscription>>>;
  /** The events of this application */
  events?: Maybe<Array<Event>>;
  /** Whether or not the application will be wrapped in aiWare as an iframe */
  headerbarEnabled?: Maybe<Scalars['Boolean']['output']>;
  iconSvg?: Maybe<Scalars['String']['output']>;
  iconUrl?: Maybe<Scalars['String']['output']>;
  id: Scalars['ID']['output'];
  isPublic?: Maybe<Scalars['Boolean']['output']>;
  /** @deprecated Application name/key validation issues. */
  key: Scalars['String']['output'];
  metadataVersion?: Maybe<Scalars['Int']['output']>;
  modifiedDateTime?: Maybe<Scalars['DateTime']['output']>;
  name: Scalars['String']['output'];
  nodeModules?: Maybe<Array<Maybe<NodeModule>>>;
  /** OAuth2 redirect URLs */
  oauth2RedirectUrls?: Maybe<Array<Maybe<Scalars['String']['output']>>>;
  organizationId?: Maybe<Scalars['ID']['output']>;
  ownerOrganizationId: Scalars['ID']['output'];
  permissionsRequired?: Maybe<Array<Maybe<Scalars['String']['output']>>>;
  sharedWithOrganizationId?: Maybe<Scalars['ID']['output']>;
  /** The signed URL for the application icon; will fallback to raw iconSvg if unable to sign. */
  signedIconSvg?: Maybe<Scalars['String']['output']>;
  /** The signed URL for the application logo; will fallback to raw iconUrl if unable to sign. */
  signedIconUrl?: Maybe<Scalars['String']['output']>;
  status?: Maybe<ApplicationStatus>;
  url?: Maybe<Scalars['String']['output']>;
  validStateActions?: Maybe<Array<Maybe<ApplicationStateAction>>>;
};


