export type AuthRoleRequirement = {
  /**
   * The name of the parent field for this resource. It also contains id(s) to query for.
   * Object-level authorization will lookup roles set to this parent resource and assigned to
   * an authorization group in the request authorization context
   */
  parentPath?: InputMaybe<Scalars['String']['input']>;
  /** The type of parent object that object-level access controls should apply to. */
  parentType?: InputMaybe<AuthResourceType>;
  /**
   * List of one or more permissions required for the operation
   * Currently that's a list of functional permissions, but potentially can be expanded to
   * some sort of policy descriptors
   */
  permissions: Array<AuthPermissionType>;
  /**
   * The name of the field parameter containing id(s) to query for.
   * Object-level authorization will lookup roles set to this resource and assigned to
   * an authorization group in the request authorization context
   */
  resourceIdFieldPath: Scalars['String']['input'];
  /**
   * The type of object that object-level access controls should apply to.
   * Must be set if allowOrgless is true and skipObjectAuthorization is false.
   */
  resourceType?: InputMaybe<AuthResourceType>;
  /**
   * If resourceType in the schema is dynamic, instead of resourceType specify the path to the
   * field in the input that specifies the resource type.
   */
  resourceTypePath?: InputMaybe<Scalars['String']['input']>;
};

