/**
 * This API creates an edge cluster for this core
 *
 * Example:
 * mutation createCluster {
 * createCluster (input: {
 * name: "YOUR_CLUSTER_NAME",
 * allowedEngines: ["all"],
 * dockerCredentials: {},
 * type: RT,
 * containerTag: "YOUR_CONTAINER_TAG",
 * paused: false,
 * memorySize: "20gb",
 * storageSize: "10gb",
 * bypassAllowedEngines: true,
 * collaborators: [],
 * subscriptions: [],
 * tags: ["aiware-agent"],
 * status: active,
 * mediaStorage: core,
 * mediaStoragePath: "",
 * serviceToken: "fake-token",
 * edgeVersion: 3,
 * }
 * ) {
 * id
 * }
 * }
 */
export type CreateCluster = {
  allowedEngines: Array<InputMaybe<Scalars['String']['input']>>;
  bypassAllowedEngines?: InputMaybe<Scalars['Boolean']['input']>;
  /** Update the cluster config */
  clusterConfig?: InputMaybe<Scalars['JSONData']['input']>;
  /** ID of the cluster group which this cluster belongs */
  clusterGroupId?: InputMaybe<Scalars['ID']['input']>;
  /**
   * Permissions granted to other organizations. Only the cluster owner
   * can view or edit this field.
   */
  collaborators?: InputMaybe<Array<CreateClusterCollaborator>>;
  containerTag?: InputMaybe<Scalars['String']['input']>;
  /** ID of the core that the cluster is pulling jobs from */
  coreId?: InputMaybe<Scalars['String']['input']>;
  dockerCredentials: Scalars['JSONData']['input'];
  edgeVersion?: InputMaybe<Scalars['Int']['input']>;
  /**
   * Indicates if this cluster represents a cluster group or an individual cluster.
   * Default is false - legacy normal cluster
   */
  isGroup?: InputMaybe<Scalars['Boolean']['input']>;
  /** media storage type (edge or core) */
  mediaStorage?: InputMaybe<MediaStorageOption>;
  /** Media storage path. Optional -- use only for edge. */
  mediaStoragePath?: InputMaybe<Scalars['String']['input']>;
  /**
   * Specify memory size in raw bytes or in human-readable
   * format such as 8gb, 1024mb, etc.
   */
  memorySize?: InputMaybe<Scalars['String']['input']>;
  name: Scalars['String']['input'];
  /** ID of the organization. Only Veritone platform components can set this value. */
  organizationId?: InputMaybe<Scalars['ID']['input']>;
  paused?: InputMaybe<Scalars['Boolean']['input']>;
  /**
   * Optionally, specify a time at which the edge cluster should
   * be restarted daily. Applies only to edge clusters.
   */
  restartTimeUTC?: InputMaybe<Scalars['Time']['input']>;
  /** Optionally, specify an api-token for cluster */
  serviceToken?: InputMaybe<Scalars['String']['input']>;
  /** Status for cluster */
  status?: InputMaybe<ClusterStatus>;
  /**
   * Specify storage size in raw bytes or in human-readable
   * format such as 8gb, 1024mb, etc.
   */
  storageSize?: InputMaybe<Scalars['String']['input']>;
  /** Set subscriptions on the cluster. */
  subscriptions?: InputMaybe<Array<InputMaybe<CreateClusterSubscription>>>;
  /** Tags for cluster */
  tags?: InputMaybe<Array<InputMaybe<Scalars['String']['input']>>>;
  type?: InputMaybe<ClusterType>;
};

