/** Input fields used to create a new engine. */
export type CreateEngine = {
  /** The engine category */
  categoryId: Scalars['String']['input'];
  /** CPU Resources required for engine to run, in milli-CPUs */
  cpuResourceMcpu?: InputMaybe<Scalars['Int']['input']>;
  /** Whether or not the engine creates a TDO */
  createsTDO?: InputMaybe<Scalars['Boolean']['input']>;
  /** The engine deployment model. See the DeploymentModel enum for options. */
  deploymentModel: DeploymentModel;
  /** An optional description for the engine. */
  description?: InputMaybe<Scalars['String']['input']>;
  /** In what way can this engine be distributed */
  distributionType?: InputMaybe<EngineDistributionType>;
  /** Edge version. Default is 3. */
  edgeVersion?: InputMaybe<Scalars['Int']['input']>;
  /** The tags associated with the engine */
  entityTags?: InputMaybe<Array<InputMaybe<EntityTagInput>>>;
  /**
   * Optionally, supply custom fields that the user can set when launching
   * the engine. See developer documentation for details.
   */
  fields?: InputMaybe<Array<CreateEngineField>>;
  /** CPU Resources required for engine to run, in milli-CPUs */
  gpuSupported?: InputMaybe<GpuSupported>;
  /** The path for an icon image */
  iconPath?: InputMaybe<Scalars['String']['input']>;
  /** Optional given id */
  id?: InputMaybe<Scalars['ID']['input']>;
  /** List of industries where the capabilities of the engine can be applied */
  industries?: InputMaybe<Array<Scalars['String']['input']>>;
  /**
   * Indicates whether or not the engine should be public -- visible to and
   * usable by users outside the creator's organization.
   * Typically an engine should not be made public until it has been fully
   * configured and tested in production.
   */
  isPublic?: InputMaybe<Scalars['Boolean']['input']>;
  /**
   * JWT rights for engine, which is used for generating jwtToken rights later
   * Limit jwtRights update to private engines only. Restricted administrative permissions are explicitly ignored.
   */
  jwtRights?: InputMaybe<JwtRightsField>;
  /**
   * Optionally, supply dependency information about this engine.
   * Currently this field cannot be set through the API
   * dependency: CreateEngineDependency
   *
   * Whether or not the engine requires a library.
   */
  libraryRequired?: InputMaybe<Scalars['Boolean']['input']>;
  /** The path for a logo image */
  logoPath?: InputMaybe<Scalars['String']['input']>;
  /** Generic Manifest for the engine based on data supplied during onboarding */
  manifest?: InputMaybe<Scalars['JSONData']['input']>;
  /** Indicates the metadata version number */
  metadataVersion?: InputMaybe<Scalars['Int']['input']>;
  /** Human-readable name for the engine */
  name?: InputMaybe<Scalars['String']['input']>;
  /** An optional price indicator for the engine. */
  price?: InputMaybe<Scalars['Int']['input']>;
  /** An optional price dimension for the engine. */
  priceDimension?: InputMaybe<PriceDimension>;
  /** Optionally, supply ID's of schemas that this engine will use as input schemas */
  schemas?: InputMaybe<Array<InputMaybe<EngineSchema>>>;
  /** Template Job definitions for standalone engine execution */
  standaloneJobTemplates?: InputMaybe<Array<CreateEngineJobTemplate>>;
  /** Testing detail includes necessary data for engine certification process */
  testingDetails?: InputMaybe<TestingDetailsField>;
  /** List of use cases the engine serves */
  useCases?: InputMaybe<Array<Scalars['String']['input']>>;
  /** Engine or Organization homepage */
  website?: InputMaybe<Scalars['String']['input']>;
};

