export enum CreateTriggerTarget {
  /**
   * Email target should provide the following kvp in the json structure of
   *   TargetType:params
   *
   *  "address":"<your_address>@<your_domain>"
   */
  Email = 'Email',
  /**
   * SMS target should provide the following kvp in the json structure of
   *   TargetType:params
   *
   *   "number": ########
   */
  Sms = 'SMS',
  /**
   * Webhook target should provide the following kvp in the json structure of
   *   TargetType:params
   *
   *   "url":"<protocol>://<your_url>
   *
   *   "headers":"{\"headerTitle\": \"headerValue\", \"Authorization\": \"Bearer sso-token\"}"
   *
   * Note that the headers value(optional) is a single string that will be parsed into a string:string map
   */
  Webhook = 'Webhook'
}

