  contentType?: Maybe<Scalars['String']['output']>;
  /** Dates tracked internally */
  createdDateTime?: Maybe<Scalars['DateTime']['output']>;
  /** Event name of notification */
  eventName?: Maybe<Scalars['String']['output']>;
  /** Event type of notification */
