export type NotificationMailbox = {
  __typename?: 'NotificationMailbox';
  details?: Maybe<Scalars['JSONData']['output']>;
  eventFilter?: Maybe<EventFilter>;
  /**
   * Special mailboxes like the default user and org mailbox have
   * ids matching the userId/applicationId
   */
  id: Scalars['ID']['output'];
  /**
   * Some frequently queried statistics from the Notifications field
   * so the clients don't have to page through to get that information
   */
  lastReceiptDateTime?: Maybe<Scalars['DateTime']['output']>;
  latestUpdateDate?: Maybe<Scalars['DateTime']['output']>;
  limit?: Maybe<Scalars['Int']['output']>;
  name: Scalars['String']['output'];
  notificationTemplate?: Maybe<Scalars['String']['output']>;
  notifications?: Maybe<NotificationList>;
  /**
   * The mailboxes can be paused and no new notification would be
   * posted until they are unpaused. This is different for silencing
   * the notifications from the UI
   */
  paused?: Maybe<Scalars['Boolean']['output']>;
  totalCount?: Maybe<Scalars['Int']['output']>;
  unreadCount?: Maybe<Scalars['Int']['output']>;
  unseenCount?: Maybe<Scalars['Int']['output']>;
};


