  auditLog: AuditLogEntryList;
  auditLogExportRequest?: Maybe<AuditLogExportRequest>;
  auditLogExportRequestForOrg?: Maybe<AuditLogExportRequestList>;
  /** Get authorization group by id. */
  authGroup: AuthGroup;
