  modifiedDateTime?: Maybe<Scalars['DateTime']['output']>;
  name?: Maybe<Scalars['String']['output']>;
  /** This contains a list of URIs engine toolkit will send completed chunks. */
  notificationUris?: Maybe<Array<Maybe<Scalars['String']['output']>>>;
