export const MeDocument = gql`
    query me($notificationsOrderBy: NotificationDateTimeField, $notificationsOrderDirection: OrderDirection, $notificationsFlags: [NotificationFlag!], $notificationsLimit: Int) {
  me {
    id
    name
    firstName
    lastName
    imageUrl
    status
    organizationId
    authGroupIds
    notifications(
      orderBy: $notificationsOrderBy
      orderDirection: $notificationsOrderDirection
      flags: $notificationsFlags
      limit: $notificationsLimit
    ) {
      count
    }
    authGroups {
      records {
        id
        name
      }
    }
    organization {
      id
      guid
      name
      status
      jsondata
      internalApplicationId
      jsondata
      notifications(
        orderBy: $notificationsOrderBy
        orderDirection: $notificationsOrderDirection
        flags: $notificationsFlags
        limit: $notificationsLimit
      ) {
        count
      }
    }
    authGroups {
      records {
        id
        name
        authClass
        parentGroups {
          records {
            id
            name
            description
          }
        }
        permissionSet {
          id
          name
          permissions
        }
        appRole {
          description
          permissions {
            records {
              id
              name
              __typename
            }
          }
        }
      }
    }
    roles {
      name
      id
      permissions {
        records {
          name
          id
        }
      }
    }
    mfaInfo {
      phoneNumber
      smsVoiceVerifiedDateTime
      gaVerifiedDateTime
      defaultOption
    }
    userSettings {
      key
      value
    }
  }
}
    `;
